import json, re

with open('/home/ubuntu/.claude-account-1/projects/-home-ubuntu--agent-ml-research-idea-gen-0509-6-projects-schema-semantic-constrained-ie/bcaaae93-c135-4568-bb9e-6ae384bb4c94/tool-results/mcp-agent-ml-research-read_registry-1779515512713.txt') as f:
    data = json.load(f)

result = json.loads(data['result'])
experiments = result['data']['experiments']

# Search broadly: any experiment with docred + beam + (200 or qwen) in EITHER id or command
for eid, exp in sorted(experiments.items()):
    eid_lower = eid.lower()
    cmd = exp.get('spec', {}).get('command', '').lower()
    combined = eid_lower + ' ' + cmd

    if 'docred' in combined and 'beam' in combined:
        # Skip llama-only ones unless they also mention qwen
        if 'llama' in eid_lower and 'qwen' not in combined:
            continue
        metrics = exp.get('metrics', {})
        print(f'{eid}')
        print(f'  status={exp.get("status")}, updated={exp.get("updated_at")}')
        if metrics:
            # Print key metrics
            for k in ['E_F1', 'E-F1', 'R_F1', 'R-F1', 'DR_pct', 'DR%', 'CF_pct', 'CF%', 'samples', 'total_samples', 'total']:
                if k in metrics:
                    print(f'  {k}: {metrics[k]}')
        else:
            print('  NO METRICS')
        # Print mode from command
        m = re.search(r'--mode\s+(\S+)', cmd)
        if m: print(f'  mode: {m.group(1)}')
        m = re.search(r'--num_beams\s+(\S+)', cmd)
        if m: print(f'  num_beams: {m.group(1)}')
        m = re.search(r'--beam_width\s+(\S+)', cmd)
        if m: print(f'  beam_width: {m.group(1)}')
        print()

# Also search for qwen docred greedy/full_s1 as baselines
print('\n=== Qwen DocRED greedy baselines (full_s1 or unconstrained, greedy) ===')
for eid, exp in sorted(experiments.items()):
    eid_lower = eid.lower()
    cmd = exp.get('spec', {}).get('command', '').lower()
    combined = eid_lower + ' ' + cmd

    if 'qwen' in combined and 'docred' in combined and 'beam' not in eid_lower:
        if exp.get('status') == 'DONE':
            metrics = exp.get('metrics', {})
            print(f'{eid}')
            if metrics:
                for k in ['E_F1', 'E-F1', 'R_F1', 'R-F1', 'DR_pct', 'CF_pct', 'samples', 'total_samples']:
                    if k in metrics:
                        print(f'  {k}: {metrics[k]}')
            m = re.search(r'--mode\s+(\S+)', cmd)
            if m: print(f'  mode: {m.group(1)}')
            print()
